function ln(id){let k=MATCH.id+':'+id;if(!db.lineups[k])db.lineups[k]={order:team(id).players.map((_,i)=>i),pos:team(id).players.map(p=>p[1]),pitcher:0};return db.lineups[k]}function safe(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function header(label,title,sub,right=''){return `<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><div class="sub">${sub}</div></div>${right}</div>`}function rankRows(){return TEAMS.map(t=>{let w=0,l=0;if(db.game?.status==='final'){if(db.game.awayId===t.id){w+=db.game.away>db.game.home?1:0;l+=db.game.away<db.game.home?1:0}if(db.game.homeId===t.id){w+=db.game.home>db.game.away?1:0;l+=db.game.home<db.game.away?1:0}}return{t,w,l}}).sort((a,b)=>b.w-a.w)}
