function lineupPage(){let t=team(db.favorite),l=ln(t.id),order=l.order;let tabs='<span class="tag blue">내 응원팀만 편성 · 선발은 KBO 발표 기준</span>';return `${header('LINEUP BUILDER','팬이 만드는 선발 라인업','선수와 타순을 선택해 우리 팀 대표 라인업을 제출하세요.',tabs)}<div class="banner">📊 <b>샘플 선수 데이터 안내</b> · 현재 기록은 임의값입니다. 팬은 응원팀 타자 9명과 타순·수비만 정합니다. 선발투수는 팬 투표에서 제외하고, 정식 연동 후 오후 5시 30분 전후 KBO가 발표한 선발을 사용합니다.</div><div class="lineup-layout"><section class="card"><div class="card-head"><h2>${t.name} · 선수 명단</h2><span class="tag blue">타자 9명 · DH</span></div><div style="overflow:auto"><table class="table"><thead><tr><th>타순</th><th>선수</th><th>수비</th><th>AVG*</th><th>OPS*</th></tr></thead><tbody>${t.players.map((p,i)=>{let n=order.indexOf(i),ops=p[2]+p[3]+p[4];return `<tr><td><select onchange="orderChange('${t.id}',${i},this.value)"><option value="-1" ${n<0?'selected':''}>제외</option>${Array.from({length:9},(_,j)=>`<option value="${j}" ${n===j?'selected':''}>${j+1}번</option>`).join('')}</select></td><td class="player">${p[0]}<small>${p[1]} · 예시</small></td><td><select onchange="positionChange('${t.id}',${i},this.value)">${['C','1B','2B','3B','SS','LF','CF','RF','DH'].map(pos=>`<option ${l.pos[i]===pos?'selected':''}>${pos}</option>`).join('')}</select></td><td>${p[2].toFixed(3).slice(1)}</td><td>${ops.toFixed(3)}</td></tr>`}).join('')}</tbody></table></div><div class="lineup-controls"><span class="tiny muted">선발투수 · ${t.pitcher[0]} (KBO 발표 샘플)</span><button class="btn btn-primary" onclick="submit('${t.id}')">라인업 제출하기　→</button></div></section><div class="grid" style="align-content:start"><section class="card"><div class="card-head"><h2>현재 라인업</h2><span class="tag">${order.length}/9</span></div><div class="order-list">${order.map((i,j)=>`<div class="order-item"><span class="order-chip">${j+1}</span><b>${t.players[i][0]}</b><span class="muted">${l.pos[i]}</span></div>`).join('')||'<div class="empty">타순을 배치하세요.</div>'}</div></section><section class="card"><div class="card-head"><h2>대표 라인업 투표</h2><span class="tag gold">MVP 임시안</span></div><div class="vote-choice"><label><input type="checkbox" checked> 이 라인업을 대표 라인업 후보로 등록</label><p class="tiny muted" style="line-height:1.6">현재 MVP에서는 라인업 제출 수를 저장합니다. 정식 서비스는 계정별 1표와 후보 라인업 결선 투표를 적용합니다.</p><button class="btn btn-green" style="width:100%" onclick="vote('${t.id}')">후보 제출 · 투표하기</button></div></section></div></div><div class="notice">*AVG, OPS는 레이아웃 샘플 숫자입니다. 선수 선택은 9명으로 제한하고 타순을 지정할 수 있습니다. 포지션·선발 변경 반영과 실제 출전 가능 선수 검증은 정식 데이터 공급원 연결 후 적용합니다.</div>`}window.pick=id=>{pickTeam=id;render()};window.orderChange=(id,i,val)=>{let l=ln(id),v=Number(val),old=l.order.indexOf(i);if(v<0)l.order=l.order.filter(x=>x!==i);else{if(old>=0)l.order.splice(old,1);l.order.splice(Math.min(v,8),0,i);l.order=l.order.slice(0,9)}persist();render()};window.positionChange=(id,i,v)=>{ln(id).pos[i]=v;persist()};window.submit=id=>{if(ln(id).order.length!==9)return notify('타순에 9명의 선수를 배치해 주세요.');persist();notify('라인업 후보로 제출했습니다.');render()};window.vote=id=>{if(ln(id).order.length!==9)return notify('먼저 9명의 타순을 완성해 주세요.');db.votes++;db.submissions++;persist();notify('라인업 후보 제출과 투표를 저장했습니다.');render()};
function hash(s){let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0}function rng(seed){let x=seed>>>0;return()=>{x=(x+0x6D2B79F5)|0;let z=x;z=Math.imul(z^z>>>15,z|1);z^=z+Math.imul(z^z>>>7,z|61);return((z^z>>>14)>>>0)/4294967296}}
function newGame(){let seed=hash(MATCH.id+JSON.stringify(db.lineups));return{id:MATCH.id,runToken:Date.now()+Math.random(),status:'running',seed,awayId:MATCH.away,homeId:MATCH.home,away:0,home:0,innings:[],plays:[],bat:{},start:new Date().toISOString(),choice:null,idx:{away:0,home:0}}}function nextBatter(g,side){let t=team(side==='away'?g.awayId:g.homeId),order=ln(t.id).order;return t.players[order[g.idx[side]++%order.length]]}window.startGame=()=>{if(db.game)return notify(db.game.status==='final'?'이미 종료된 공식 경기입니다.':'경기가 이미 진행 중입니다.');if(!confirm('공식 경기를 오후 6시 슬롯으로 시작합니다. 이 경기는 한 번만 실행되며 결과가 저장됩니다. 계속할까요?'))return;db.game=newGame();persist();advanceMatch()};function playPA(g,side,inn){let random=rng(g.seed+g.plays.length*919),p=nextBatter(g,side),opp=team(side==='away'?g.homeId:g.awayId),rate=Math.max(.15,Math.min(.38,p[2]+.015-(opp.pitcher[1]-.25)*.22)),bb=Math.max(.035,Math.min(.15,p[3]*.3)),hr=Math.max(.012,Math.min(.075,p[5]));if(g.choiceUsed==='aggressive')rate+=.018;if(g.choiceUsed==='sacrifice')rate-=.008;rate=Math.max(.12,Math.min(.42,rate));let rem=Math.max(0,rate-hr),pr={'1B':rem*.70,'2B':rem*.27,'3B':rem*.02,HR:hr,BB:bb,HBP:.012,K:.21,OUT:0,GDP:0},base=g.base||[null,null,null],outs=g.outs||0;pr.OUT=Math.max(0,1-pr['1B']-pr['2B']-pr['3B']-pr.HR-pr.BB-pr.HBP-pr.K);if(base[0]&&outs<2){pr.GDP=pr.OUT*.10;pr.OUT-=pr.GDP}let counts={'1B':0,K:0,BB:0,GDP:0,HR:0,'2B':0,'3B':0,HBP:0,OUT:0};for(let n=0;n<PA_TRIALS;n++){let x=random(),sum=0,hit=false;for(let k of Object.keys(counts)){sum+=pr[k];if(x<sum){counts[k]++;hit=true;break}}if(!hit)counts.OUT++}let kind=Object.keys(counts).reduce((best,k)=>counts[k]>counts[best]?k:best,'OUT'),runs=0;if(kind==='HR'){runs=1+base.filter(Boolean).length;g.base=[null,null,null]}else if(kind==='3B'){runs=base.filter(Boolean).length;g.base=[null,null,p[0]]}else if(kind==='2B'){runs=(base[1]?1:0)+(base[2]?1:0);g.base=[null,p[0],base[0]]}else if(kind==='1B'){runs=base[2]?1:0;g.base=[p[0],base[0],base[1]]}else if(kind==='BB'||kind==='HBP'){if(base[0]){if(base[1]){if(base[2])runs++;base[2]=base[1]}base[1]=base[0]}base[0]=p[0];g.base=base}else if(kind==='GDP'){outs+=2;g.base=[null,base[1],base[2]]}else if(kind==='K'||kind==='OUT')outs++;g.outs=outs;let b=g.bat[p[0]]||(g.bat[p[0]]={AB:0,H:0,'2B':0,'3B':0,HR:0,BB:0,HBP:0,K:0,GDP:0,R:0});if(['OUT','K','GDP','1B','2B','3B','HR'].includes(kind))b.AB++;if(['1B','2B','3B','HR'].includes(kind))b.H++;if(kind==='2B'||kind==='3B'||kind==='HR')b[kind]=(b[kind]||0)+1;if(kind==='BB')b.BB++;if(kind==='HBP')b.HBP++;if(kind==='GDP')b.GDP++;if(kind==='K')b.K++;b.R+=runs;g[side]+=runs;let row=g.innings[inn-1]||(g.innings[inn-1]={away:0,home:0});row[side]+=runs;let record={inn,side,batter:p[0],kind,runs,outs,base:[...g.base],distribution:{trials:PA_TRIALS,counts:counts,selected:kind}};g.plays.push(record);return record}
function showDistribution(i){let p=db.game&&db.game.plays[i];if(!p||!p.distribution)return notify('이 타석에는 분포 데이터가 없습니다.');let d=p.distribution,names={'1B':'단타',K:'삼진',BB:'볼넷',GDP:'병살타',HR:'홈런','2B':'2루타','3B':'3루타',HBP:'몸에 맞는 공',OUT:'아웃'};let rows=Object.entries(d.counts).sort((a,b)=>b[1]-a[1]).map(([k,n])=>'<div class="dist-row '+(k===d.selected?'chosen':'')+'"><span>'+names[k]+'</span><div class="dist-track"><i style="width:'+(n/d.trials*100)+'%"></i></div><b>'+n+'회</b><small>'+Math.round(n/d.trials*100)+'%</small></div>').join('');let old=document.getElementById('dist-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend','<div class="modal-backdrop" id="dist-modal" onclick="if(event.target===this)this.remove()"><section class="dist-modal"><button class="modal-close" onclick="document.getElementById(\'dist-modal\').remove()">×</button><div class="eyebrow">PLATE APPEARANCE · '+d.trials.toLocaleString()+' TRIALS</div><h2>'+safe(p.batter)+' 타석 결과 분포</h2><p>'+p.inn+'회 '+(p.side==='away'?'초':'말')+' · 결과 <b>'+names[d.selected]+'</b> · 최빈 결과를 적용했습니다.</p><div class="dist-list">'+rows+'</div><div class="notice">같은 타자·투수 능력 조건에서 '+d.trials.toLocaleString()+'회 표본 시뮬레이션한 빈도입니다. 이 분포에서 가장 많이 나온 결과를 실제 타석 결과로 반영했습니다.</div></section></div>')}
