function gamePage(){let g=db.game;if(g&&g.status==='final')return resultPage(g);let html=header('GAME CENTER','공식 경기 센터','실제 라인업 발표 확인 후 18:00–18:20에 공식 경기 진행')+'<div class="banner">중요 장면에서는 진행이 멈춥니다. 팬들은 작전 투표를 하고, 제한 시간이 끝나면 최다 득표 선택지가 적용됩니다.</div><div class="game-layout"><section class="card scoreboard"><div class="score-title"><h2>'+team(MATCH.away).short+' vs '+team(MATCH.home).short+'</h2><span class="tag">'+(g?'진행 중':'경기 전')+'</span></div>';
if(g) html+=scoreTable(g); else html+='<div class="empty"><p>오늘 오후 6시에 시작할 경기입니다.</p><button class="btn btn-primary" onclick="startGame()">샘플 경기 시작 · 1회만 실행</button></div>';
html+='</section><section class="card situation"><div class="score-title"><h2>경기 상황 · 팬 작전 투표</h2></div>';
if(g){html+='<div class="vote-box"><b>현재 상황</b><p class="tiny muted">'+g.plays.length+'타석 · '+g.away+' : '+g.home+'</p>';
if(g.ballot){html+='<b>중요 상황! 작전을 골라주세요.</b><div class="tiny muted">마감까지 <b id="countdown">15초</b> · 최다 득표 적용</div><div class="vote-options">'+g.ballot.choices.map(c=>'<button onclick="choosePlay(\''+c.id+'\')">'+c.label+' <b>'+c.percent+'%</b></button>').join('')+'</div>'}else html+='<span class="tiny muted">다음 주요 상황에서 투표가 열립니다.</span>';
html+='</div><div class="timeline">'+g.plays.slice(-16).reverse().map(p=>'<div class="play"><div class="play-time">'+p.inn+'회 '+(p.side==='away'?'초':'말')+'</div><div><strong>'+p.batter+'</strong> <span class="muted">'+kindName(p.kind)+(p.runs?' · '+p.runs+'득점':'')+'</span><button class="detail-button" onclick="showDistribution(${g.plays.indexOf(p)})">결과 분포</button></div></div>').join('')+'</div>'}else html+='<div class="empty">경기 시작 후 타석 로그와 팬 투표가 표시됩니다.</div>';
return html+'</section></div><p class="notice">현재는 브라우저 저장소를 이용한 데모입니다. 전체 사용자 동일 결과 및 서버의 중복 실행 방지는 DB 연동 뒤 보장합니다.</p>'}
function advanceMatch(){let g=db.game;if(!g||g.status!=='running'||g.ballot)return;g.inning=g.inning||1;g.half=g.half||'away';g.outs=g.outs||0;g.base=g.base||[null,null,null];if(g.inning>=9&&g.half==='home'&&g.home>g.away){g.status='final';persist();render();return}if(g.inning>12){g.status='final';g.tiebreak='12회 종료 무승부';persist();render();return}if(g.choice){g.choiceUsed=g.choice;g.choice=null}let p=playPA(g,g.half,g.inning);if(g.choiceUsed){g.plays[g.plays.length-1].choice=g.choiceUsed;g.choiceUsed=null}if(g.half==='home'&&g.inning>=9&&g.home>g.away){g.status='final'}if(g.outs>=3){g.outs=0;g.base=[null,null,null];if(g.half==='away'){if(g.inning>=9&&g.home>g.away)g.status='final';else g.half='home'}else{if(g.inning>=9&&g.home!==g.away)g.status='final';else if(g.inning>=12){g.status='final';g.tiebreak='12회 종료 무승부'}else{g.inning++;g.half='away'}}}persist();render();if(g.status==='final'){notify('공식 경기가 종료되고 결과가 고정됐습니다.');return}if((p.base.filter(Boolean).length>=2&&p.outs<3)||(p.runs>0&&p.outs<3)){g.ballot={choices:[{id:'normal',label:'기본 작전 유지',percent:39},{id:'aggressive',label:'강공 · 적극적으로 한 점 노리기',percent:36},{id:'sacrifice',label:'작전 · 주자를 한 베이스 더 보내기',percent:25}]};persist();render();let timer=15;const tick=()=>{if(!db.game?.ballot)return;let el=$('#countdown');if(el)el.textContent=timer+'초';if(timer--<=0){closeBallot(true);return}setTimeout(tick,1000)};tick();return}setTimeout(advanceMatch,180)}
function kindName(k){return({HR:'홈런','3B':'3루타','2B':'2루타','1B':'단타',BB:'볼넷',HBP:'몸에 맞는 공',GDP:'병살타',K:'삼진',OUT:'아웃',SAC:'희생번트 성공',BUNT_FAIL:'번트 실패 · 타자 아웃'})[k]||k}function scoreTable(g){let n=Math.max(9,g.innings.length);return `<div style="overflow:auto"><table class="score-table"><thead><tr><th>팀</th>${Array.from({length:n},(_,i)=>`<th>${i+1}</th>`).join('')}<th>R</th></tr></thead><tbody><tr><td>${team(g.awayId).short}</td>${Array.from({length:n},(_,i)=>`<td>${g.innings[i]?.away??'·'}</td>`).join('')}<td class="total">${g.away}</td></tr><tr><td>${team(g.homeId).short}</td>${Array.from({length:n},(_,i)=>`<td>${g.innings[i]?.home??'·'}</td>`).join('')}<td class="total">${g.home}</td></tr></tbody></table></div>`}function resultPage(g){return `${header('FINAL · OFFICIAL RESULT','경기 결과','공식 샘플 시뮬레이션 · seed '+g.seed)}<div class="result-head"><div><div class="eyebrow" style="color:#9ba9bc">FANBALL MATCH · ${MATCH.date}</div><h2>${team(g.awayId).name} vs ${team(g.homeId).name}</h2></div><div class="final-score">${g.away}<span>:</span>${g.home}</div></div><div class="game-layout"><section class="card scoreboard"><div class="score-title"><h2>이닝별 스코어</h2><span class="tag">${g.innings.length}회 종료</span></div>${scoreTable(g)}<h3 style="font-size:13px;margin:22px 0 8px">팬볼 타자 기록</h3><div style="overflow:auto"><table class="table"><thead><tr><th>선수</th><th>AB</th><th>H</th><th>SH</th><th>2B</th><th>3B</th><th>HR</th><th>BB</th><th>K</th><th>AVG</th></tr></thead><tbody>${Object.entries(g.bat).map(([n,b])=>`<tr><td class="player">${n}</td><td>${b.AB}</td><td>${b.H}</td><td>${b.SH||0}</td><td>${b['2B']}</td><td>${b['3B']||0}</td><td>${b.HR}</td><td>${b.BB}</td><td>${b.K}</td><td>${b.AB?(b.H/b.AB).toFixed(3).slice(1):'.000'}</td></tr>`).join('')}</tbody></table></div></section><section class="card situation"><div class="score-title"><h2>타석별 경기 로그</h2><span class="tag blue">${g.plays.length} 타석</span></div><div class="timeline">${[...g.plays].reverse().map(p=>`<div class="play"><div class="play-time">${p.inn}회 ${p.side==='away'?'초':'말'}</div><div><strong>${p.batter}</strong> <span class="muted">${kindName(p.kind)}${p.runs?` · ${p.runs}득점`:''}</span><button class="detail-button" onclick="showDistribution(${g.plays.indexOf(p)})">결과 분포</button></div></div>`).join('')}</div></section></div><p class="notice">현재는 간이 샘플 확률 모델입니다. 타석당 100,000회 표본은 결과 분포를 안정적으로 보여주기 위한 설정이며 실제 KBO 기록 기반 확률로 교체해야 합니다. 정식 구현에서는 타석 결과 확률을 전날까지의 기록으로 추정하고, 아웃·진루·자책점·이닝 등 기록 규칙을 전면 보강합니다.</p>`}
function recordsPage(){let rows=rankRows(),g=db.game;return `${header('LEAGUE & STATS','팬볼 순위 · 기록','실제 KBO 통계와 구분된 팬볼 가상 기록입니다.')}<div class="banner">팬볼 선수 기록은 실제 KBO 기록과 별도 저장하며 선수 능력치에는 반영하지 않습니다. 현재 기록은 이 브라우저에서 생성한 샘플 경기 결과입니다.</div><div class="two-col" style="margin-top:0"><section class="card"><div class="card-head"><h2>구단 순위</h2><span class="tag blue">FANBALL</span></div><div class="rank-row"><div>#</div><div>구단</div><div class="record">승-패</div><div class="win">승률</div></div>${rows.map((x,i)=>`<div class="rank-row"><div class="rank ${i===0?'first':''}">0${i+1}</div><div class="team-mini"><div class="mini-ball">${x.t.abbr}</div>${x.t.name}</div><div class="record">${x.w}-${x.l}</div><div class="win">${x.w+x.l?(x.w/(x.w+x.l)).toFixed(3).slice(1):'—'}</div></div>`).join('')}</section><section class="card"><div class="card-head"><h2>최근 팬볼 경기</h2><span class="tag">${g?.status==='final'?1:0} 경기</span></div>${g?.status==='final'?`<div class="schedule-row"><div class="datebox">FINAL</div><div class="schedule-desc">${team(g.awayId).short} ${g.away} : ${g.home} ${team(g.homeId).short}<small>공식 샘플 경기</small></div><button class="link" onclick="go('game')">보기 →</button></div>`:'<div class="empty">아직 종료된 팬볼 경기가 없습니다.</div>'}</section></div><section class="card" style="margin-top:17px"><div class="card-head"><h2>팬볼 누적 타격 기록</h2><span class="tag">샘플 통계</span></div>${g?.status==='final'?`<div style="overflow:auto"><table class="table"><thead><tr><th>선수</th><th>타수</th><th>안타</th><th>2루타</th><th>홈런</th><th>볼넷</th><th>삼진</th><th>타율</th><th>OPS</th></tr></thead><tbody>${Object.entries(g.bat).map(([n,b])=>`<tr><td class="player">${n}</td><td>${b.AB}</td><td>${b.H}</td><td>${b.SH||0}</td><td>${b['2B']}</td><td>${b['3B']||0}</td><td>${b.HR}</td><td>${b.BB}</td><td>${b.K}</td><td>${b.AB?(b.H/b.AB).toFixed(3).slice(1):'.000'}</td><td>—</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">경기 결과가 쌓이면 선수별 기록을 표시합니다.</div>'}</section><p class="notice">OPS 및 투수 평균자책점은 공식 기록 계산에 필요한 세부 정보가 아직 충분히 집계되지 않아 비워둡니다. 향후 실제 경기 기록 기준으로 계산합니다.</p>`}
function go(p){page=p;render()}window.go=go;function render(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent={home:'홈',lineup:'라인업 투표',game:'경기 센터',records:'순위 · 기록'}[page];app.innerHTML=page==='home'?home():page==='lineup'?lineupPage():page==='game'?gamePage():recordsPage()}$('#nav').onclick=e=>{let b=e.target.closest('button[data-page]');if(b)go(b.dataset.page)};$('#favorite').innerHTML=TEAMS.map(t=>`<option value="${t.id}">${t.name}</option>`).join('');$('#favorite').value=db.favorite;$('#favorite').onchange=e=>{db.favorite=e.target.value;pickTeam=db.favorite;persist();render()};render();
